update public.complications c set onset_at = timestamptz '2026-09-10 15:10:00+05:30'
  from public.procedures p where p.id = c.procedure_id and p.case_code = 'PCI-2026-005' and p.created_by is null
  and c.complication = 'access_site_haematoma' and c.onset_at = timestamptz '2026-09-10 13:49:00+05:30';
update public.procedures set haemostasis_method = 'manual_compression'
  where case_code = 'PCI-2026-005' and created_by is null and haemostasis_method = 'other';
insert into public.procedure_events (procedure_id, event, actor, payload)
  select p.id, 'data_corrected', null, jsonb_build_object('fields', jsonb_build_array('discharges.red_flags'),
    'change', 'standard red flags added: 2 urgency headings + 9 items (was empty)', 'note', 'owner-approved synthetic data correction 2026-10-15')
  from public.procedures p where p.created_by is null and p.case_code in ('PCI-2026-002', 'PCI-2026-004', 'PCI-2026-006', 'PCI-2026-007', 'PCI-2026-009', 'PCI-2026-011', 'PCI-2026-012', 'PCI-2026-014', 'PCI-2026-016', 'CAG-2026-018', 'CAG-2026-019');
insert into public.procedure_events (procedure_id, event, actor, payload)
  select p.id, 'data_corrected', null, jsonb_build_object('fields', jsonb_build_array('complications.onset_at', 'procedures.haemostasis_method'),
    'change', 'access-site haematoma onset 13:49 -> 15:10 IST (after sheath removal at 14:49); haemostasis other -> manual_compression', 'note', 'owner-approved synthetic data correction 2026-10-15')
