alter table public.discharges enable trigger guard_reviewed_child;
alter table public.complications enable trigger guard_reviewed_child;
alter table public.procedures enable trigger guard_procedure_review;
do $$
declare n int;
begin
  select count(*) into n from public.discharges d join public.procedures p on p.id = d.procedure_id
    where p.created_by is null and p.case_code in ('PCI-2026-002', 'PCI-2026-004', 'PCI-2026-006', 'PCI-2026-007', 'PCI-2026-009', 'PCI-2026-011', 'PCI-2026-012', 'PCI-2026-014', 'PCI-2026-016', 'CAG-2026-018', 'CAG-2026-019') and cardinality(d.red_flags) = 11;
  if n <> 11 then raise exception 'red flags: expected 11 discharges with 11 items, got %', n; end if;
  select count(*) into n from public.complications c join public.procedures p on p.id = c.procedure_id
    where p.case_code = 'PCI-2026-005' and p.created_by is null and c.onset_at = timestamptz '2026-09-10 15:10:00+05:30';
  if n <> 1 then raise exception '005 onset: expected 1, got %', n; end if;
  select count(*) into n from public.procedures where case_code = 'PCI-2026-005' and created_by is null and haemostasis_method = 'manual_compression';
  if n <> 1 then raise exception '005 haemostasis: expected 1, got %', n; end if;
  select count(*) into n from public.procedure_events where event = 'data_corrected' and payload->>'note' = 'owner-approved synthetic data correction 2026-10-15';
  if n <> 12 then raise exception 'events: expected 12, got %', n; end if;
  select count(*) into n from pg_trigger where not tgisinternal and tgenabled = 'D'
    and tgrelid in ('public.discharges'::regclass, 'public.complications'::regclass, 'public.procedures'::regclass);
  if n <> 0 then raise exception 'triggers still disabled: %', n; end if;
end $$;
